async function download(url, name) {
  const target = path.join(cache, name);
  if (fs.existsSync(target) && fs.statSync(target).size > 1000) return target;
  const response = await fetch(url, { headers: { "user-agent": "History-Go-place-production/1.0" } });
  if (!response.ok) throw new Error(`${response.status} ${url}`);
  fs.writeFileSync(target, Buffer.from(await response.arrayBuffer()));
  return target;
}
async function img(source, target, width, height, position = "centre") {
  const output = path.join(root, target); fs.mkdirSync(path.dirname(output), { recursive: true });
  await sharp(source).resize(width, height, { fit: "cover", position }).webp({ quality: 88 }).toFile(output);
}

