const stories=[{id:"st_forsvarsmuseet_samlingen_som_matte_reddes",quality_profile:"episode_v1",type:"conflict",title:"Samlingen som måtte reddes",year:1941,place_id:placeId,summary:"Okkupasjonen stanset museumsplanen, spredte samlingene og kostet tusenvis av gjenstander.",story:"Hærmuseet var formelt opprettet i 1940, men fikk ikke utvikle seg som planlagt. I 1941 oppløste nazistyret museumskomiteen.\n\nOkkupasjonsmakten tok gjenstander, blant annet kanoner som skulle smeltes om. Da Paléet brant, gikk om lag 3000 objekter tapt. Resten av samlingene ble spredt til blant annet Oscarshall, gruvene på Kongsberg og gårder ved Eidsvoll og Slitu.\n\nI 1946 kom samlingene tilbake til Akershus. Returen løste ikke plassproblemet, men gjorde det mulig å bygge videre mot det offentlige museet som åpnet i 1978. Episoden viser at museumshistorie også handler om sårbar logistikk, tap og institusjonell kontroll.",episode:{actors:["museumskomiteen og de ansatte","okkupasjonsmyndighetene","institusjoner og gårder som tok imot evakuerte gjenstander"],date:"1941–1946",action:"Komiteen ble oppløst, gjenstander gikk tapt og resten av samlingen ble evakuert.",consequence:"Samlingene vendte tilbake til Akershus i 1946, men måtte fortsatt flyttes mellom lokaler fram til 1978."},sources:[{title:"SNL – Forsvarshistorisk museum",url:urls.snl},{title:"Sikt – Forsvarsmuseets endringshistorie",url:urls.sikt}],tags:["museumshistorie","okkupasjon","samling","bevaring"],related_people:[],related_places:[],next_scenes:[{place_id:placeId,reason:"Følg returen i 1946 og åpningen i Hovedarsenalet i 1978."}],score:{narrative:3,historical:2,source:4,play_value:3,originality:3,total:15},arc:{start:"Et nyopprettet hærmuseum mister komiteen sin.",middle:"Samlingen blir plyndret, rammet av brann og evakuert.",end:"Gjenstandene vender tilbake og blir grunnlag for et senere offentlig museum."}}];
